/* From Uiverse.io by elijahgummer  - Tags: animation, black, checkbox, hamburger, arrow */
.__UIV_SCOPE__ .toggle-checkbox {
  display: none;
}

.__UIV_SCOPE__ .hamburger {
  display: flex;
  flex-direction: column;
  justify-content: space-around;
  width: 35px;
  height: 24px;
  cursor: pointer;
}

.__UIV_SCOPE__ .hamburger .bar {
  width: 100%;
  height: 4px;
  background-color: #333;
  border-radius: 10px;
  transition:
    transform 0.3s ease,
    opacity 0.3s ease;
  position: relative;
}

.__UIV_SCOPE__ .toggle-checkbox:checked + .hamburger .bar:nth-child(2) {
  transform: translate(0px, 10px);
  opacity: 0;
  transition-delay: 0.3s;
}

.__UIV_SCOPE__ .toggle-checkbox:checked + .hamburger .bar:nth-child(3) {
  transform: translate(0px, -10px);
  transition-delay: 0s;
}

.__UIV_SCOPE__ .toggle-checkbox:checked + .hamburger .bar:nth-child(1) {
  transform: rotate(-45deg) scale(0.7);
  transition-delay: 0.6s;
}
.__UIV_SCOPE__ .toggle-checkbox:checked + .hamburger .bar:nth-child(3) {
  transform: rotate(45deg) scale(0.7);
  transition-delay: 0.6s;
}
